<?php
require 'auth.php';require_login();require 'db.php';require 'layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$animal=(int)$_POST['animal_id'];$food=trim($_POST['food_type']);$qty=trim($_POST['quantity']);$time=str_replace('T',' ',$_POST['feeding_time']);$uid=$_SESSION['user_id'];$s=$conn->prepare('INSERT INTO feeding_schedule(animal_id,food_type,quantity,feeding_time,user_id) VALUES(?,?,?,?,?)');$s->bind_param('isssi',$animal,$food,$qty,$time,$uid);$s->execute();$fid=$conn->insert_id;$cons=trim($_POST['food_consumed']??'');$beh=trim($_POST['behavior']??'');$obs=trim($_POST['observation']??'');$oth=trim($_POST['others']??'');$n=$conn->prepare('INSERT INTO feeding_notes(feeding_id,food_consumed,behavior,observation,others) VALUES(?,?,?,?,?)');$n->bind_param('issss',$fid,$cons,$beh,$obs,$oth);$n->execute();header('Location: feeding.php?msg='.urlencode('Feeding schedule saved.'));exit;}
$animals=$conn->query('SELECT animal_id,name FROM animal ORDER BY name');$rows=$conn->query('SELECT f.*,a.name,u.full_name,n.food_consumed,n.behavior,n.observation FROM feeding_schedule f JOIN animal a ON f.animal_id=a.animal_id JOIN users u ON f.user_id=u.user_id LEFT JOIN feeding_notes n ON f.feeding_id=n.feeding_id ORDER BY f.feeding_time DESC');page_top('Feeding');
?><div class="section-head"><h1 class="page-title">Feeding Schedule</h1></div><?php if($_SESSION['role']==='volunteer'):?><form class="form-card form-grid" method="post"><select name="animal_id" required><option value="">Animal</option><?php while($a=$animals->fetch_assoc()):?><option value="<?=$a['animal_id']?>"><?=h($a['name'])?></option><?php endwhile;?></select><input name="food_type" placeholder="Food type" required><input name="quantity" placeholder="Quantity" required><input type="datetime-local" name="feeding_time" required><input name="food_consumed" placeholder="Food consumed"><input name="behavior" placeholder="Behavior"><textarea class="full" name="observation" placeholder="Observation"></textarea><textarea class="full" name="others" placeholder="Other notes"></textarea><button class="btn full">Save Feeding Entry</button></form><?php endif;?><div class="section-head"><h2>Feeding history</h2></div><div class="table-wrap"><table><tr><th>Animal</th><th>Time</th><th>Food</th><th>Quantity</th><th>Consumed</th><th>Behavior</th><th>Volunteer</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=h($r['name'])?></td><td><?=h($r['feeding_time'])?></td><td><?=h($r['food_type'])?></td><td><?=h($r['quantity'])?></td><td><?=h($r['food_consumed']??'—')?></td><td><?=h($r['behavior']??'—')?></td><td><?=h($r['full_name'])?></td></tr><?php endwhile;?></table></div><?php page_bottom(); ?>
